const raw = String($json.output ?? '');

// Convert visible "\n" into real line breaks
let text = raw
  .replace(/\\n/g, '\n')
  .replace(/\\r/g, '')
  .replace(/\r\n/g, '\n')
  .trim();

// Remove any HTML the AI may already have generated
text = text.replace(/<[^>]*>/g, '');

// Escape characters that can break Telegram HTML
text = text
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// Convert Markdown bold to Telegram HTML bold
text = text.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');

// Make numbered steps slightly cleaner
text = text.replace(
  /(^|\n)(\d+)\.\s+/g,
  '$1<b>$2.</b> '
);

// Remove excessive blank lines
text = text.replace(/\n{3,}/g, '\n\n');

const telegramMessage = `<b>🛒 NovaCart Customer Support</b>

${text}

<i>Thank you for contacting NovaCart Support.</i>`;

return [
  {
    json: {
      telegram_message: telegramMessage
    }
  }
];

function escapeHtml(text) {
  return String(text ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

return $input.all().map(item => {
  const data = item.json;

  const priority = escapeHtml(data.priority);
  const ticketId = escapeHtml(data.ticket_id);
  const customerName = escapeHtml(data.customer_name || 'Unknown');
  const complaint = escapeHtml(data.complaint || 'No complaint provided');

  const needDatabase = data.need_database === true ? '✅ Yes' : '❌ No';
  const appendDatabase = data.need_database_append === true ? '✅ Yes' : '❌ No';

  const telegram_message = `
🚨 <b>HIGH PRIORITY COMPLAINT</b> 🚨

━━━━━━━━━━━━━━━━━━

🎫 <b>Ticket ID:</b>
<code>${ticketId}</code>

👤 <b>Customer:</b>
${customerName}

⚠️ <b>Priority:</b>
🔴 ${priority}

📝 <b>Complaint:</b>
<i>${complaint}</i>

━━━━━━━━━━━━━━━━━━

🔍 <b>Transaction / Database Check:</b>
${needDatabase}

📋 <b>Complaint Registered:</b>
${appendDatabase}

━━━━━━━━━━━━━━━━━━

👨‍💼 <b>Manager Action Required</b>

Please review this complaint and take the necessary action.

🤖 <i>Escalyn Complaint Management System</i>
`.trim();

  return {
    json: {
      ...data,
      telegram_message
    }
  };
});
